<p class="lead">Coordinate the handoff, record actual collection, and confirm it with both the donor and receiver. Token verification is single-use.</p>
<?php if (!$data['pickups']): ?><p class="empty-state">No pickups assigned yet. <?php if ($user['role']==='receiver'): ?><a class="underlined" href="/donations">Discover food to collect.</a><?php elseif ($user['role']==='volunteer'): ?><a class="underlined" href="/profile">Set your volunteer availability.</a><?php endif ?></p><?php endif ?>
<?php foreach ($data['pickups'] as $pickup): $isDonor=(int)$pickup['donor_id']===(int)$user['id'];$isReceiver=(int)$pickup['receiver_user']===(int)$user['id'];$isVolunteer=(int)($pickup['volunteer_id'] ?? 0)===(int)$user['id']; ?>
<article class="panel spaced" id="pickup-<?= e($pickup['id']) ?>"><div class="card-top"><h2><a href="/donations/<?= e($pickup['donation_id']) ?>"><?= e($pickup['name']) ?></a></h2><?php badge($pickup['status']); ?></div><p>Pickup #<?= e($pickup['id']) ?> · Receiver: <?= e($pickup['receiver_name']) ?> · <?= e($pickup['quantity_kg']) ?> kg reserved</p><p><?= e($pickup['address']) ?> · Deadline <?php stamp($pickup['deadline']); ?></p><?php if ($pickup['scheduled_at']): ?><p>Scheduled: <?php stamp($pickup['scheduled_at']); ?> · Volunteer: <?= e($pickup['volunteer_name'] ?? 'Receiver self-collection') ?></p><?php endif ?>
<a class="underlined" target="_blank" rel="noopener" href="https://www.openstreetmap.org/directions?to=<?= e($pickup['latitude']) ?>%2C<?= e($pickup['longitude']) ?>">Open pickup location ↗</a>
<?php if (in_array($pickup['status'],['accepted','scheduled'],true) && ($isDonor || $isReceiver)): ?><details <?= $pickup['status']==='accepted' ? 'open' : '' ?>><summary><?= $pickup['status']==='accepted' ? 'Schedule pickup and generate QR' : 'Reschedule / replace pickup token' ?></summary><form data-api="/api/pickups/schedule"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php field('scheduled_at','Collection starts at (local time)','datetime-local',$pickup['scheduled_at'] ?? '', 'required');choice('volunteer_id','Collector',[''=>'Receiver self-collection']+array_column($data['volunteers'],'name','id'),$pickup['volunteer_id'] ?? '',false);formend('Schedule and generate one-use QR'); ?><div class="token-output" hidden></div></details><?php endif ?>
<?php if ($pickup['status']==='scheduled' && ($isReceiver || $isVolunteer)): ?><details><summary>Verify token and record collection</summary><form data-api="/api/pickups/verify"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php field('token','Pickup token','text','','required pattern="[a-f0-9]{64}" maxlength="64"'); ?><button type="button" class="quiet-button" data-scan>Scan QR with camera</button><video class="qr-video" playsinline hidden></video><p class="scan-status" role="status"></p><?php field('collected_kg','Actual collected weight (kg)','number','','required min="0.001" step="0.001" max="' . e($pickup['quantity_kg']) . '"');formend('Verify and record collection'); ?></details><?php endif ?>
<?php if ($pickup['status']==='collected'): ?><p><strong>Actual collected: <?= e($pickup['collected_kg']) ?> kg</strong></p><p>Donor confirmation: <?= $pickup['donor_confirmed'] ? 'recorded' : 'pending' ?> · Receiver confirmation: <?= $pickup['receiver_confirmed'] ? 'recorded' : 'pending' ?></p>
<?php if (($isDonor && !$pickup['donor_confirmed']) || ($isReceiver && !$pickup['receiver_confirmed'])): ?><form data-api="/api/pickups/complete" data-confirm="Confirm the recorded collection?"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php if ($isReceiver):field('distributed_kg','Weight actually distributed (kg; enter 0 if not yet distributed)','number',0,'required min="0" max="' . e($pickup['collected_kg']) . '" step="0.001"');endif;formend('Confirm collection'); ?><?php endif ?><?php endif ?>
<?php if (in_array($pickup['status'],['accepted','scheduled'],true) && ($isDonor || $isReceiver || $isVolunteer)): ?><details><summary>Report a failed pickup<?= !$isVolunteer ? ' or cancel' : '' ?></summary><form data-api="/api/pickups/fail" data-confirm="Record this pickup as failed and release the reserved capacity?"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php field('reason','Failure reason','textarea','','required');formend('Report failed pickup'); ?><?php if (!$isVolunteer): ?><form data-api="/api/pickups/cancel" data-confirm="Cancel this pickup and release capacity?"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php field('reason','Cancellation reason','textarea','','required');formend('Cancel pickup'); ?><?php endif ?></details><?php endif ?>
<?php if ($pickup['status']==='completed' && ($isDonor || $isReceiver)): ?><details><summary>Leave collection feedback</summary><form data-api="/api/reviews"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php choice('rating','Rating',[5=>'5 — Excellent',4=>'4 — Good',3=>'3 — Fair',2=>'2 — Poor',1=>'1 — Very poor']);field('comment','Feedback','textarea');formend('Save feedback'); ?></details><?php endif ?>
<?php if ($isReceiver && in_array($pickup['status'],['collected','completed'],true)): ?><details><summary>Update the amount distributed</summary><form data-api="/api/pickups/distributed"><input type="hidden" name="id" value="<?= e($pickup['id']) ?>"><?php field('distributed_kg','Total weight distributed so far (kg)','number','','required min="0" step="0.001" max="' . e($pickup['collected_kg']) . '"');formend('Update distribution record'); ?></details><?php endif ?>
</article><?php endforeach ?>
